// ─── Countdown ────────────────────────────────────────────────────────────────

function CountdownTimer() {
  const target = new Date('2026-11-26T09:00:00')
  const [t, setT] = useState({ d: 0, h: 0, m: 0, s: 0 })

  useEffect(() => {
    const tick = () => {
      const diff = target.getTime() - Date.now()
      if (diff <= 0) return
      setT({
        d: Math.floor(diff / 86400000),
        h: Math.floor((diff % 86400000) / 3600000),
        m: Math.floor((diff % 3600000) / 60000),
        s: Math.floor((diff % 60000) / 1000),
      })
    }
    tick()
    const id = setInterval(tick, 1000)
    return () => clearInterval(id)
  }, [])

  const units = [
    { val: t.d, label: 'Days', color: G.blue },
    { val: t.h, label: 'Hours', color: G.red },
    { val: t.m, label: 'Minutes', color: G.yellow },
    { val: t.s, label: 'Seconds', color: G.green },
  ]

  return (
    <div className="flex gap-3 sm:gap-6 justify-center flex-wrap">
      {units.map(({ val, label, color }) => (
        <div key={label} className="flex flex-col items-center">
          <div
            className="w-16 h-16 sm:w-20 sm:h-20 rounded-2xl flex items-center justify-center text-white font-bold text-2xl sm:text-3xl tabular-nums shadow-lg"
            style={{ background: color }}
          >
            {String(val).padStart(2, '0')}
          </div>
          <span className="text-xs mt-2 font-medium" style={{ color: G.darkgray }}>{label}</span>
        </div>
      ))}
    </div>
  )
}

// ─── Navbar ───────────────────────────────────────────────────────────────────

function LangSelector() {
  const [open, setOpen] = useState(false)
  const [lang, setLang] = useState<'EN' | 'FR'>('EN')

  const flags: Record<'EN' | 'FR', string> = { EN: '🇬🇧', FR: '🇫🇷' }
  const other = lang === 'EN' ? 'FR' : 'EN'

  return (
    <div className="relative">
      <button
        onClick={() => setOpen(o => !o)}
        className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-semibold transition-all select-none"
        style={{ border: '1.5px solid #c4c7cc', color: '#5f6368', background: 'transparent', cursor: 'pointer' }}
      >
        <span style={{ fontSize: 16, lineHeight: 1 }}>{flags[lang]}</span>
        <span style={{ letterSpacing: '0.02em' }}>{lang}</span>
        <svg
          width="10" height="10" viewBox="0 0 10 10" fill="none"
          style={{ transition: 'transform 0.2s', transform: open ? 'rotate(180deg)' : 'rotate(0deg)' }}
        >
          <path d="M2 3.5L5 6.5L8 3.5" stroke="#9aa0a6" strokeWidth="1.5" strokeLinecap="round"/>
        </svg>
      </button>

      {open && (
        <div
          className="absolute right-0 mt-2 rounded-xl overflow-hidden"
          style={{ background: '#fff', border: '1.5px solid #e8eaed', boxShadow: '0 4px 16px rgba(0,0,0,0.1)', minWidth: 110, zIndex: 100 }}
        >
          {(['EN', 'FR'] as const).map(l => (
            <button
              key={l}
              onClick={() => { setLang(l); setOpen(false) }}
              className="w-full flex items-center gap-2 px-4 py-2.5 text-sm font-medium transition-all text-left"
              style={{
                background: lang === l ? G.lightgray : '#fff',
                color: '#1a1a1a',
                fontWeight: lang === l ? 700 : 400,
              }}
              onMouseEnter={e => { if (lang !== l) e.currentTarget.style.background = G.lightgray }}
              onMouseLeave={e => { if (lang !== l) e.currentTarget.style.background = '#fff' }}
            >
              <span style={{ fontSize: 16 }}>{flags[l]}</span>
              <span>{l === 'EN' ? 'English' : 'Français'}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

function Navbar({ onNavigate }: { onNavigate?: (page: string) => void }) {
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 10)
    window.addEventListener('scroll', fn)
    return () => window.removeEventListener('scroll', fn)
  }, [])

  const links = ['About', 'Speakers', 'Schedule', 'Sponsorship', 'Speakers Night']

  const goHomeAnchor = (anchor: string) => (e: React.MouseEvent) => {
    e.preventDefault()
    setMobileOpen(false)
    if (onNavigate) {
      onNavigate('home')
      setTimeout(() => {
        document.getElementById(anchor)?.scrollIntoView({ behavior: 'smooth' })
      }, 80)
    } else {
      document.getElementById(anchor)?.scrollIntoView({ behavior: 'smooth' })
    }
  }

  return (
    <header
      className="fixed top-0 left-0 right-0 z-50 transition-all duration-300"
      style={{
        background: scrolled ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0)',
        backdropFilter: scrolled ? 'blur(20px) saturate(180%)' : 'none',
        WebkitBackdropFilter: scrolled ? 'blur(20px) saturate(180%)' : 'none',
        boxShadow: scrolled ? '0 1px 0 rgba(0,0,0,0.08)' : 'none',
        height: '5rem',
      }}
    >
      <div className="max-w-6xl mx-auto h-full px-6 flex items-center justify-between">
        {/* Logo */}
        <a href="#" className="flex items-center no-underline" onClick={e => { if (onNavigate) { e.preventDefault(); onNavigate('home') } }}>
          <img src={devFestLuxLogo} alt="DevFest Luxembourg" style={{ height: 44, width: 'auto' }} />
        </a>

        {/* Desktop nav */}
        <nav className="hidden md:flex items-center gap-1">
          {links.map(l => l === 'Speakers Night' ? (
            <a
              key={l}
              href="#tickets"
              onClick={goHomeAnchor('tickets')}
              className="inline-flex items-center gap-1.5 ml-2 px-5 py-2 rounded-full text-sm font-bold text-white transition-all"
              style={{
                background: 'linear-gradient(135deg, #f953c6 0%, #b91d73 100%)',
                boxShadow: '0 2px 10px rgba(249,83,198,0.4)',
              }}
              onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-1px)'; e.currentTarget.style.boxShadow = '0 4px 16px rgba(249,83,198,0.55)' }}
              onMouseLeave={e => { e.currentTarget.style.transform = ''; e.currentTarget.style.boxShadow = '0 2px 10px rgba(249,83,198,0.4)' }}
            >
              <span>Speakers Night</span>
            </a>
          ) : l === 'Sponsorship' ? (
            <a
              key={l}
              href="#"
              onClick={e => { e.preventDefault(); if (onNavigate) onNavigate('sponsoring') }}
              className="px-4 py-2 rounded-full text-sm font-medium transition-all"
              style={{ color: G.darkgray }}
              onMouseEnter={e => { e.currentTarget.style.background = G.lightgray; e.currentTarget.style.color = '#1a1a1a' }}
              onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = G.darkgray }}
            >
              {l}
            </a>
          ) : (
            <a
              key={l}
              href={`#${l.toLowerCase()}`}
              onClick={goHomeAnchor(l.toLowerCase())}
              className="px-4 py-2 rounded-full text-sm font-medium transition-all"
              style={{ color: G.darkgray }}
              onMouseEnter={e => { e.currentTarget.style.background = G.lightgray; e.currentTarget.style.color = '#1a1a1a' }}
              onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = G.darkgray }}
            >
              {l}
            </a>
          ))}
          <a
            href="#tickets"
            onClick={goHomeAnchor('tickets')}
            className="btn-register ml-2 px-5 py-2 rounded-full text-sm font-bold"
          >
            Tickets
          </a>
          <div className="ml-2">
            <LangSelector />
          </div>
        </nav>

        {/* Mobile hamburger */}
        <button className="md:hidden p-2" onClick={() => setMobileOpen(!mobileOpen)}>
          <div className="w-6 flex flex-col gap-1.5">
            {[0, 1, 2].map(i => (
              <span key={i} className="block h-0.5 rounded-full transition-all" style={{ background: '#1a1a1a' }} />
            ))}
          </div>
        </button>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div className="md:hidden px-6 pb-4 flex flex-col gap-1" style={{ background: 'rgba(255,255,255,0.95)', borderTop: '1px solid #f0f0f0' }}>
          {links.map(l => l === 'Speakers Night' ? (
            <a key={l} href="#tickets" onClick={goHomeAnchor('tickets')} className="inline-flex items-center gap-1.5 py-3 text-sm font-bold" style={{ color: '#b91d73', borderBottom: '1px solid #f8f8f8' }}>
              <span>Speakers Night</span>
            </a>
          ) : l === 'Sponsorship' ? (
            <a key={l} href="#" onClick={e => { e.preventDefault(); setMobileOpen(false); if (onNavigate) onNavigate('sponsoring') }} className="py-3 text-sm font-medium" style={{ color: '#1a1a1a', borderBottom: '1px solid #f8f8f8' }}>{l}</a>
          ) : (
            <a key={l} href={`#${l.toLowerCase()}`} onClick={goHomeAnchor(l.toLowerCase())} className="py-3 text-sm font-medium" style={{ color: '#1a1a1a', borderBottom: '1px solid #f8f8f8' }}>{l}</a>
          ))}
          <a href="#tickets" onClick={goHomeAnchor('tickets')} className="btn-register mt-3 py-3 text-center rounded-full text-sm font-bold">Tickets</a>
          <div className="mt-3 flex justify-start">
            <LangSelector />
          </div>
        </div>
      )}
    </header>
  )
}

