function SpeakerCard({ s }: { s: typeof SPEAKERS[0] }) {
  const [hov, setHov] = useState(false)

  return (
    <div
      className="rounded-2xl overflow-hidden transition-all duration-300 cursor-pointer"
      style={{
        background: '#fff',
        boxShadow: hov ? '0 16px 48px rgba(0,0,0,0.12)' : '0 2px 12px rgba(0,0,0,0.06)',
        transform: hov ? 'translateY(-6px)' : 'none',
      }}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
    >
      {/* Photo */}
      <div className="relative overflow-hidden" style={{ height: 200 }}>
        <img
          src={s.image}
          alt={s.name}
          className="w-full h-full object-cover transition-transform duration-500"
          style={{ transform: hov ? 'scale(1.06)' : 'scale(1)', objectPosition: (s as any).objectPosition || 'center' }}
        />
        <div className="absolute inset-0" style={{ background: 'linear-gradient(to top, rgba(0,0,0,0.4) 0%, transparent 50%)' }} />
        {/* Track badge */}
        <span
          className="absolute top-3 right-3 text-xs font-bold px-2.5 py-1 rounded-full text-white"
          style={{ background: s.trackColor }}
        >
          {s.track}
        </span>
      </div>

      {/* Info */}
      <div className="p-5">
        <div className="font-bold text-base mb-0.5" style={{ color: '#1a1a1a' }}>{s.name}</div>
        <div className="text-sm font-medium mb-3" style={{ color: s.trackColor }}>{s.role}{s.company ? ` · ${s.company}` : ''}</div>
        <p className="text-xs leading-relaxed" style={{ color: G.darkgray }}>
          "{s.talk}"
        </p>
      </div>
    </div>
  )
}

