// ─── Schedule ─────────────────────────────────────────────────────────────────

function Schedule() {
  const [track, setTrack] = useState<'all' | 'Web' | 'AI/ML' | 'Cloud' | 'Mobile' | 'Security' | 'Design' | 'Android'>('all')

  const tracks = ['all', 'Web', 'AI/ML', 'Cloud', 'Mobile', 'Security', 'Design', 'Android'] as const

  const filtered = SCHEDULE.filter(item =>
    track === 'all' || item.type === 'break' || item.type === 'keynote' || item.track === track
  )

  return (
    <section id="schedule" className="py-24" style={{ background: G.lightgray }}>
      <div className="max-w-4xl mx-auto px-6">
        <div className="text-center mb-12">
          <span className="inline-block text-sm font-bold px-3 py-1 rounded-full mb-4" style={{ background: '#e6f4ea', color: G.green }}>Schedule</span>
          <h2 className="text-4xl sm:text-5xl font-black mb-4" style={{ color: '#1a1a1a', letterSpacing: '-0.02em' }}>
            November <span style={{ color: G.green }}>26, 2026</span>
          </h2>
        </div>

        {/* Track filter */}
        <div className="flex flex-wrap gap-2 justify-center mb-10">
          {tracks.map(t => (
            <button
              key={t}
              onClick={() => setTrack(t)}
              className="px-4 py-1.5 rounded-full text-xs font-bold transition-all capitalize"
              style={{
                background: track === t ? G.blue : '#fff',
                color: track === t ? '#fff' : G.darkgray,
                border: `2px solid ${track === t ? G.blue : '#e8eaed'}`,
              }}
            >
              {t === 'all' ? 'All Tracks' : t}
            </button>
          ))}
        </div>

        {/* Items */}
        <div className="space-y-2">
          {filtered.map((item, i) => {
            const isBreak = item.type === 'break'
            const isKeynote = item.type === 'keynote'

            return (
              <div
                key={i}
                className="flex gap-4 rounded-xl p-4 items-start"
                style={{
                  background: isBreak ? '#fff' : isKeynote ? '#e8f0fe' : '#fff',
                  border: isKeynote ? `2px solid ${G.blue}` : isBreak ? '1px solid #f0f0f0' : `1px solid #e8eaed`,
                  borderLeft: item.color ? `4px solid ${item.color}` : isKeynote ? `4px solid ${G.blue}` : isBreak ? '4px solid #e0e0e0' : '4px solid transparent',
                }}
              >
                <span className="font-bold text-sm shrink-0 w-12 pt-0.5" style={{ color: G.darkgray, fontVariantNumeric: 'tabular-nums' }}>
                  {item.time}
                </span>
                <div className="flex-1 min-w-0">
                  <div className="font-bold text-sm" style={{ color: '#1a1a1a' }}>{item.title}</div>
                  {item.speaker && (
                    <div className="text-xs mt-0.5" style={{ color: item.color || G.blue }}>{item.speaker}</div>
                  )}
                  {item.track && !isKeynote && (
                    <span className="inline-block text-xs px-2 py-0.5 rounded-full mt-1 font-medium" style={{ background: `${item.color || G.blue}18`, color: item.color || G.blue }}>
                      {item.track}
                    </span>
                  )}
                </div>
                {isKeynote && (
                  <span className="shrink-0 text-xs font-bold px-2 py-0.5 rounded-full text-white" style={{ background: G.blue }}>Keynote</span>
                )}
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

