// copy-to-clipboard helper
function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false)
  const copy = () => {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    })
  }
  return (
    <button
      onClick={copy}
      title="Copy email"
      className="w-12 h-12 rounded-full flex items-center justify-center transition-all"
      style={{ background: copied ? 'rgba(52,168,83,0.25)' : 'rgba(255,255,255,0.12)', border: '1.5px solid rgba(255,255,255,0.2)', cursor: 'pointer' }}
      onMouseEnter={e => { if (!copied) e.currentTarget.style.background = 'rgba(255,255,255,0.2)' }}
      onMouseLeave={e => { if (!copied) e.currentTarget.style.background = 'rgba(255,255,255,0.12)' }}
    >
      {copied ? (
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M20 6L9 17l-5-5" stroke="#34a853" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
      ) : (
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><rect x="9" y="9" width="13" height="13" rx="2" stroke="rgba(255,255,255,0.8)" strokeWidth="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" stroke="rgba(255,255,255,0.8)" strokeWidth="2"/></svg>
      )}
    </button>
  )
}

