// ─── App ──────────────────────────────────────────────────────────────────────

export default function App() {
  const [page, setPage] = useState<'home' | 'sponsoring' | 'deck'>('home')

  const navigate = (p: string) => {
    setPage(p as 'home' | 'sponsoring' | 'deck')
    window.scrollTo(0, 0)
  }

  if (page === 'deck') {
    return <SponsorDeck onNavigate={navigate} />
  }

  if (page === 'sponsoring') {
    return <SponsoringPage onNavigate={navigate} />
  }

  return (
    <div>
      <Navbar onNavigate={navigate} />
      <Hero onNavigate={navigate} />
      <About />
      <WhatToExpect />
      <CallForPapers />
      <Speakers />
      <Schedule />
      <Venue />

      <Tickets />
      <Register />
      <Organizers />
      <CommunityPartners />
      <Footer />
    </div>
  )
}
